```python
def factorial(i):
    result = 1
    for num in range(1, i + 1):
        result *= num
    return result

def sum_to_i(i):
    return int((i * (i + 1)) / 2)

def f(n):
    result = []
    for i in range(1, n+1):
        if i % 2 == 0:
            result.append(factorial(i))
        else:
            result.append(sum_to_i(i))
    return result
```
