def count_nums(arr):
    def get_sum_of_digits(n):
        """Helper function to calculate the sum of digits"""
        if n < 0:
            return -1 * sum([int(i) for i in str(-1*n)[1:]])  # remove first digit and sum remaining digits
        else:
            return sum([int(i) for i in str(n)])

    count = 0
