def histogram(test):
    # Create an empty dictionary to store letters and their counts.
    letter_counts = {}

    # Split the string into words (letters) using space as delimiter.
    words = test.split(' ')

    for word in words:
        if word not in letter_counts:
            # If a letter is not yet in the dictionary, add it with count 1.
            letter_counts[word] = 1
        else:
            # If a letter is already in the dictionary, increment its count by 1.
            letter_counts[word] += 1

    max_count = max(letter_counts.values()) if letter_counts else 0

    return {k: v for k, v in letter_counts.items() if v == max_count}
```
