```python
def match_parens(lst):
    stack = []  # Stack to keep track of open parentheses

    for string in lst:
        for char in string:
            if char == '(':
                stack.append(char)  # Push onto the stack when an open parenthesis is found
            elif char == ')' and len(stack) > 0:
                stack.pop()  # Pop from the stack when a close parenthesis is found and there's at least one open parenthesis in the stack
            else:
                return 'No'  # If we find a close parenthesis but the stack is empty, it means there's no matching open parenthesis for this close parenthesis. So, return 'No'.

    if len(stack) > 0:  # After checking all characters in both strings, if there are still unmatched open parentheses left in the stack, return 'No'
        return 'No'
    else:
        return 'Yes'  # If no unmatched open parenthesis is found after checking all characters, it means we have a good string. So, return 'Yes'.
```

