```python
def change_base(x: int, base: int):
    if base < 2 or base > 36:
        raise ValueError("Base must be between 2 and 36")

    # Convert to binary, octal or hexadecimal based on the base
    if base == 2:
        return bin(x)[2:]
    elif base == 8:
        return oct(x)[1:]
    elif base == 16:
        return hex(x)[2:]

    # Convert to any other base using int() function
    else:
        return str(int(str(x), 10)) if x >= 10 else str(x)
```
