```python
def is_prime(n):
    if n <= 1 or (n % 2 == 0 and n > 2): 
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return False
    return True

def digit_sum(n):
    return sum(int(digit) for digit in str(n))

def skjkasdkd(lst):
    prime_values = [num for num in lst if is_prime(num)]
    if not prime_values:  # If no primes are found, return 0
        return 0
    else:
        return max(digit_sum(val) for val in prime_values)
```
